Certainly! Below is the implementation of the `find_path` function, where `graph` is a dictionary with nodes as keys, and the value is a list of adjacent nodes. The function returns a list of nodes forming the path from `start` to `goal`. If there is no path, it will return `None`.

```python
def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    def dfs(current_node, path):
        # If the current node is the goal, add it to the path
        if current_node == goal:
            return path + [current_node]
        for neighbor in graph[current_node]:
            if neighbor not in path:  # Avoid cycles
                result = dfs(neighbor, path + [current_node])
                if result is not None:
                    return result
        return None

    return dfs(start, [start])

# Example usage:
graph = {
    'A': ['B', 'C'],
    'B': ['D', 'G'],
    'C': ['E', 'F'],
    'D': ['G'],
    'E': ['G'],
    'F': [],
    'G': []
}

print(find_path(graph, 'A', 'G'))  # Expected output: ['A', 'C', 'F', 'G']
print(find_path(graph, 'A', 'D'))  # Expected output: ['A', 'B', 'D']
print(find_path(graph, 'A', 'H'))  # Expected output: None (H is not in the graph)
```
